import * as G from './gm-core.js';
import {ATTRS,num,clamp} from './rules.js';
import {SEED,LIBRARY,MAPS} from './seed.js';
const KEY='arquivo-beyonder-mestre-v1',$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const roles={adversary:'Adversário',ally:'Aliado',neutral:'NPC',player:'Jogador'};
const tabs=[['mesa','⌂','Mesa'],['fichas','♙','Fichas'],['combate','⚔','Combate'],['investigacao','⌕','Investigação'],['biblioteca','▤','Biblioteca'],['registros','✎','Registros']];
const titles={mesa:'Mesa do mestre',fichas:'Pessoas & adversários',combate:'Controle de combate',investigacao:'Quadro de investigação',biblioteca:'Biblioteca do mestre',registros:'Registros & backups'};
let state,broken=null,history=[],toastTimer,selected=null,sheetTab='perfil',page='mesa',query='',filter='',libraryQuery='',libraryFolder='',installPrompt=null,mapZoom=1,importMode='gm';
try{const raw=localStorage.getItem(KEY);state=raw?G.parseBackup(raw):G.createState();}catch(e){try{broken=localStorage.getItem(KEY)||String(e);}catch{broken=String(e);}state=G.createState();}
const sess=()=>G.session(state),ent=id=>G.entity(state,id),cur=()=>ent(selected);
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function save(){if(broken)return;try{const raw=G.backup(state);if(raw.length>5000000)throw Error('Estado excede 5 MB. Exporte e arquive sessões antigas.');localStorage.setItem(KEY,raw);$('#save-status').textContent='Salvo neste aparelho';$('#save-status').style.color='';}catch(e){$('#save-status').textContent='Não salvo · exporte um backup';$('#save-status').style.color='var(--red)';toast('Não foi possível salvar no aparelho. Seus dados continuam abertos: exporte um backup.');}}
function mutate(label,fn,redraw=true){if(broken){toast('Há um arquivo local que precisa ser recuperado. Abra Registros.');return;}const before=G.clone(state);try{fn();if(label)G.record(state,label);history.push(before);if(history.length>25)history.shift();save();if(redraw)render();else $('#undo').disabled=!history.length;return true;}catch(e){state=before;toast(e.message||'Não foi possível concluir.');return false;}}
function btn(action,label,cls='outline small',data=''){return `<button type="button" data-action="${action}" class="${cls}" ${data}>${label}</button>`;}
const opts=(pairs,value)=>pairs.map(([k,v])=>`<option value="${esc(k)}" ${String(k)===String(value)?'selected':''}>${esc(v)}</option>`).join('');
function field(label,path,value,type='text',extra=''){return `<label>${esc(label)}<input type="${type}" data-field="${esc(path)}" value="${esc(value)}" ${extra}></label>`;}
function area(label,path,value){return `<label>${esc(label)}<textarea data-field="${esc(path)}">${esc(value)}</textarea></label>`;}
function select(label,path,value,pairs){return `<label>${esc(label)}<select data-field="${esc(path)}">${opts(pairs,value)}</select></label>`;}
function input(label,name,value='',type='text',extra=''){return `<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function formArea(label,name,value=''){return `<label>${esc(label)}<textarea name="${esc(name)}">${esc(value)}</textarea></label>`;}
function card(title,body,extra='',cls=''){return `<section class="card ${cls}"><div class="card-title"><h3>${title}</h3>${extra}</div>${body}</section>`;}
function pill(text,kind=''){return `<span class="pill ${kind}">${esc(text)}</span>`;}
function resources(e,compact=false){const d=G.stats(e);return `<div class="${compact?'combat-bars':''}">${[['hp','Vida'],['san','Sanidade'],['spirit','Espiritualidade']].map(([k,t])=>`<div class="resource"><div class="resource-head"><span>${t}</span><b>${e.resources[k]} <span class="muted">/ ${d[k]??'—'}</span></b></div><div class="bar ${k}"><span style="width:${d[k]?clamp(e.resources[k]/d[k]*100,0,100):0}%"></span></div></div>`).join('')}</div>`;}
function statline(e){const d=G.stats(e);return `<div class="statline">${[['df','DF'],['dm','DM'],['rm','RM'],['armor','Armadura'],['initiative','Iniciativa']].map(([k,t])=>`<div>${t}<b>${k==='initiative'&&d[k]>=0?'+':''}${d[k]??'—'}</b></div>`).join('')}</div>`;}
const initials=e=>e.name.split(' ').filter(s=>s.length>2).slice(0,2).map(s=>s[0]).join('');
function flags(e){return `<div class="actions">${e.dead?pill('Morto','red'):''}${e.fatigue?pill(`Fadiga ${e.fatigue}`,'red'):''}${e.corruption?pill(`Marca ${e.corruption}/6`,'gold'):''}${e.conditions.map(c=>pill(c)).join('')}</div>`;}
function entityCard(e){return `<article class="card entity-card"><div class="entity-heading"><div class="avatar">${esc(initials(e))}</div><div><h3>${esc(e.name)}</h3>${pill(roles[e.role],e.role==='adversary'?'red':e.role==='ally'?'teal':'')}</div></div><p>${esc(e.location||e.faction||'Sem local definido')}</p>${resources(e)}${statline(e)}<div class="section-gap">${flags(e)}</div><div class="actions">${btn('open-entity','Abrir ficha','outline gold small',`data-id="${esc(e.id)}"`)}${btn('combat-add','+ Encontro','outline small',`data-id="${esc(e.id)}"`)}</div></article>`;}
function empty(title,text,action=''){return `<div class="empty"><span class="big-number">◇</span><h3>${title}</h3><p>${text}</p>${action}</div>`;}
function render(){
 $('#nav').innerHTML=tabs.map(([id,icon,t])=>btn('nav',`<span>${icon}</span><span>${t}</span>`,id===page?'active':'',`data-page="${id}" ${id===page?'aria-current="page"':''}`)).join('');
 $('#page-title').textContent=titles[page];$('#session-picker').innerHTML=opts(state.sessions.map(s=>[s.id,s.name]),state.activeSession);$('#undo').disabled=!history.length;
 $('#main').innerHTML=({mesa:renderDesk,fichas:renderSheets,combate:renderCombat,investigacao:renderClues,biblioteca:renderLibrary,registros:renderRecords}[page])();
 if(broken)$('#main').insertAdjacentHTML('afterbegin','<p class="warning">Seu arquivo salvo não pôde ser lido. Ele foi preservado e as alterações estão bloqueadas. Abra Registros para exportar o original ou restaurar um backup.</p>');
}
function clockView(c){return `<div class="clock"><div class="clock-head"><b>${esc(c.name)}</b><div class="clock-controls">${btn('clock-step','−','outline small',`data-id="${esc(c.id)}" data-delta="-1" aria-label="Diminuir ${esc(c.name)}"`)}<span>${c.value}/${c.max}</span>${btn('clock-step','+','outline small',`data-id="${esc(c.id)}" data-delta="1" aria-label="Avançar ${esc(c.name)}"`)}</div></div><div class="clock-segments" aria-hidden="true">${Array.from({length:c.max},(_,i)=>`<span class="${i<c.value?'on':''}"></span>`).join('')}</div><small>${esc(c.note)}</small></div>`;}
function renderDesk(){const s=sess(),scene=SEED.scenes.find(v=>v.id===s.scene)||SEED.scenes[0],players=state.entities.filter(e=>e.role==='player');return `<div class="grid asymmetric"><div class="stack">${card('A segunda voz',`<div class="eyebrow">CENA ATUAL</div><h2 style="margin:12px 0">${esc(scene.title)}</h2><p>${esc(scene.goal)}</p><p class="muted">${esc(scene.pressure)}</p><div class="actions">${btn('note','Abrir roteiro da cena','',`data-id="${scene.id}"`)}${scene.encounter?btn('encounter','Preparar encontro','outline',`data-id="${scene.encounter}"`):''}${btn('nav','Ver investigação','outline',`data-page="investigacao"`)}</div>`,'','highlight')}
 ${card('Personagens da mesa',players.length?`<div class="grid">${players.map(e=>`<div><div class="list-item-head"><b>${esc(e.name)}</b>${btn('resource','Ajustar','outline small',`data-id="${e.id}"`)}</div>${resources(e)}${flags(e)}<p class="hint">Episódios de marca nesta sessão: ${e.markChecks}/2</p></div>`).join('')}</div>`:empty('Sua mesa ainda está vazia','Importe as fichas do app dos jogadores ou crie personagens aqui.',btn('import-players','Importar jogadores','')))}
 ${card('Pronto para mestrar',`<div class="grid three mobile-two">${btn('map','⌘ Fluxo da sessão','map-tile',`data-id="01-Fluxo-da-sessao"`)}${btn('map','⌕ Teia de pistas','map-tile',`data-id="02-Teia-de-pistas"`)}${btn('map','♙ Pessoas e interesses','map-tile',`data-id="03-Pessoas-e-interesses"`)}</div><div class="divider"></div><div class="actions">${btn('note','Painel de mesa','outline',`data-id="00-Painel-de-mesa"`)}${btn('note','Se os jogadores fizerem isso…','outline',`data-id="M04-Se-os-jogadores-fizerem-isso"`)}${btn('floorplan','Planta do instituto','outline',`data-id="mestre"`)}</div>`)}
 ${card('Lembretes da sessão',`<div class="stack">${[['avisos','Apresentar riscos antes de uma exposição deliberada.'],['pistas','Método adequado entrega a pista essencial; teste define custo e detalhe.'],['marca','Marca inicial 1/6. No máximo 2 episódios de teste por personagem.'],['cura','Sair e conter o foco não curam. Sequência 7 também não cura.'],['rene','René só entra se anunciado, disponível e pertinente.']].map(([k,t])=>`<label class="check"><input type="checkbox" data-checklist="${k}" ${s.checklist.includes(k)?'checked':''}>${t}</label>`).join('')}</div>`)}
 </div><div class="stack">${card('Relógios da sessão',s.clocks.map(clockView).join('')+`<p class="hint">Relógios não causam Corrupção automaticamente.</p>`,btn('new-clock','+ Relógio','text-button'))}${card('Roteiro navegável',`<div class="scene-list">${SEED.scenes.map((v,i)=>btn('scene',`<span>${String(i+1).padStart(2,'0')}</span><span>${esc(v.title.split(' · ')[1])}<small>${esc(v.goal)}</small></span><span>›</span>`,`scene-button ${s.scene===v.id?'active':''}`,`data-id="${v.id}"`)).join('')}</div>`)}${card('Últimos acontecimentos',s.log.length?`<div class="log">${s.log.slice(-5).reverse().map(logView).join('')}</div>`:'<p class="hint">Alterações e rolagens aparecerão aqui.</p>')}</div></div>`;}
function renderSheets(){if(selected&&cur())return renderSheet(cur());const filtered=state.entities.filter(e=>(!filter||e.role===filter)&&norm([e.name,e.faction,e.location,e.notes].join(' ')).includes(norm(query)));return `<div class="toolbar"><input id="entity-search" class="search" type="search" placeholder="Buscar pessoa, facção ou local…" value="${esc(query)}" aria-label="Buscar fichas"><select id="entity-filter" aria-label="Filtrar fichas">${opts([['','Todas as fichas'],...Object.entries(roles)],filter)}</select>${btn('new-entity','+ Nova ficha','')}${btn('import-players','Importar jogadores','outline')}</div><p class="hint">${filtered.length} fichas · NPCs prontos mantêm os totais do livro. Fichas Beyonder usam atributos e perícias para calcular os valores.</p><div class="grid three entity-grid">${filtered.map(entityCard).join('')}</div>${!filtered.length?empty('Nenhuma ficha encontrada','Ajuste a busca ou crie uma nova ficha.'):''}`;}
function renderSheet(e){const d=G.stats(e);let body='';if(sheetTab==='perfil')body=`<div class="grid">${card('Identidade e interpretação',`<div class="form-grid">${field('Nome','name',e.name)}${select('Papel','role',e.role,Object.entries(roles))}${field('Facção','faction',e.faction)}${field('Local / cena','location',e.location)}<div class="wide">${area('O que quer agora','motive',e.motive)}</div><div class="wide">${area('O que teme','fear',e.fear)}</div><div class="wide">${area('Falas prontas e interpretação','quote',e.quote)}</div></div>`)}${card('Informações do mestre',`${area('O que sabe / bônus prontos','knowledge',e.knowledge)}<div class="section-gap">${area('Segredos','secret',e.secret)}</div><div class="section-gap">${area('Tática','tactics',e.tactics)}</div><div class="section-gap">${area('Moral e retirada','morale',e.morale)}</div><div class="section-gap">${area('Saque e recompensas','loot',e.loot)}</div>`)}</div><div class="section-gap">${card('Anotações livres',area('Histórico, vínculos, aparência e consequências','notes',e.notes))}</div>`;
 if(sheetTab==='valores')body=`<div class="grid">${card(e.mode==='auto'?'Atributos e cálculos':'Perfil abreviado',`<p class="hint">${e.mode==='auto'?'Máximos, DF, DM, RM e iniciativa são calculados. Aumentar o máximo não cura.':'Totais manuais, como no material da sessão. Campos vazios de Vida/defesas significam “não definido”. Sanidade máxima é sempre 100.'}</p>${e.mode==='auto'?`<div class="form-grid">${select('Caminho','path',e.path,Object.entries(G.PATHS).map(([k,v])=>[k,v.name]))}${select('Sequência','sequence',e.sequence,[[9,'9'],[8,'8'],[7,'7']])}</div><div class="divider"></div><div class="form-grid four">${Object.entries(ATTRS).map(([k,v])=>field(v,`attrs.${k}`,e.attrs[k],'number','min="0" max="5"')).join('')}</div><div class="divider"></div><div class="form-grid">${Object.entries({hp:'Ajuste Vida',spirit:'Ajuste Espiritualidade',df:'Ajuste DF',dm:'Ajuste DM',rm:'Ajuste RM',armor:'Armadura extra'}).map(([k,v])=>field(v,`adjust.${k}`,e.adjust[k],'number','min="-100" max="100"')).join('')}</div><p class="hint">Vida = 10 + 4×VIT + 2×Grau; Espiritualidade = 10 + 3×VON + 2×INT + 5×Grau. Grau = 10 − Sequência. Alterar Sequência aqui não distribui atributos: registre o avanço aprovado na mesa.</p>`:`<div class="form-grid three">${Object.entries({hp:'Vida máxima',spirit:'Espiritualidade máxima',df:'DF',dm:'DM',rm:'RM',armor:'Armadura',initiative:'Bônus de iniciativa',move:'Movimento (m)'}).map(([k,v])=>field(v,`stats.${k}`,e.stats[k]??'','number',`min="${k==='initiative'?-99:0}" max="9999"`)).join('')}</div><div class="divider"></div><p class="hint">Atributos abaixo servem para testes avulsos e sobrevivência; não recalculam o perfil pronto. Ajuste se necessário.</p><div class="form-grid four">${Object.entries(ATTRS).map(([k,v])=>field(v,`attrs.${k}`,e.attrs[k],'number','min="0" max="5"')).join('')}</div>`}`)}${card('Recursos e estado',`${resources(e)}${statline(e)}<div class="section-gap actions">${btn('resource','Dano, cura e recursos','',`data-id="${e.id}"`)}${btn('spirit','Usar Espiritualidade','outline',`data-id="${e.id}"`)}</div><div class="divider"></div><div class="form-grid">${field('Fadiga (0–3)','fatigue',e.fatigue,'number','min="0" max="3"')}${field('Corrupção (0–6)','corruption',e.corruption,'number','min="0" max="6"')}${field('Falhas de morte (0–2)','deathFails',e.deathFails,'number','min="0" max="2"')}${field('Episódios de marca nesta sessão','markChecks',e.markChecks,'number','min="0" max="2"')}</div><div class="divider"></div><div class="checks">${Object.entries(G.CONDITIONS).map(([k,v])=>`<label class="check" title="${esc(v)}"><input type="checkbox" data-condition="${esc(k)}" ${e.conditions.includes(k)?'checked':''}>${esc(k)}</label>`).join('')}</div><div class="section-gap">${area('Ferimentos e tratamento','wounds',e.wounds)}</div><div class="section-gap actions">${btn('death','Teste de morte','danger small',`data-id="${e.id}"`)}${btn('stabilize','Estabilizar (já aprovado)','outline small',`data-id="${e.id}"`)}${btn('mark','Teste de marca','outline small',`data-id="${e.id}"`)}${btn('crisis','Teste de crise','outline small',`data-id="${e.id}"`)}</div><p class="hint">Marca e crise não são resolvidas automaticamente. Teste a marca uma única vez por ocorrência; máximo 2 episódios nesta sessão. Abalado e Fadiga entram nos testes. Outros efeitos dependem do contexto.</p>`)}<div class="wide">${card('Perícias',`<div class="form-grid four">${G.SKILLS.map(k=>field(k,`skills.${k}`,e.skills[k]||0,'number',`min="0" max="${e.mode==='auto'?12-e.sequence:12}"`)).join('')}</div><p class="hint">Perícias somam ao atributo em testes. Os ataques abaixo já guardam o bônus total.</p>`)}</div></div>`;
 if(sheetTab==='arsenal')body=`<div class="grid">${card('Ataques',e.attacks.map((a,i)=>`<div class="list-item"><div class="list-item-head"><h4>${esc(a.name)}</h4>${btn('edit-attack','Editar','outline small',`data-index="${i}"`)}</div><p><b>${a.bonus>=0?'+':''}${a.bonus}</b> contra ${a.kind==='san'?'DM':'DF'} · dano ${esc(a.damage)} ${a.kind==='san'?'de Sanidade':''} · ${esc(a.range)} · custo ${a.cost} ESP${a.usesAmmo?`<br>Carregada ${a.ammo}/${a.capacity} · reserva ${a.reserve} · recarga ${a.reload}/ação`:''}</p><p>${esc(a.notes)}</p><div class="actions">${btn('attack','Atacar','outline gold small',`data-id="${e.id}" data-index="${i}"`)}${a.usesAmmo?btn('reload','Recarregar','outline small',`data-id="${e.id}" data-index="${i}"`):''}${btn('delete-entry','Excluir','text-button',`data-kind="attacks" data-index="${i}"`)}</div></div>`).join('')||'<p class="hint">Sem ataques registrados. Adicione bônus total, dano e alcance.</p>',btn('edit-attack','+ Ataque','text-button',`data-index="-1"`))}${card('Habilidades Beyonder',e.abilities.map((a,i)=>`<div class="list-item"><div class="list-item-head"><h4>${esc(a.name)} ${pill(`${a.cost} ESP`,'gold')}</h4>${btn('edit-ability','Editar','outline small',`data-index="${i}"`)}</div><p>${esc(a.notes)}</p><div class="actions">${btn('use-ability','Usar','outline gold small',`data-id="${e.id}" data-index="${i}"`)}${btn('delete-entry','Excluir','text-button',`data-kind="abilities" data-index="${i}"`)}</div></div>`).join('')||'<p class="hint">Registre poderes definidos e usos livres aprovados para o Caminho.</p>',btn('edit-ability','+ Habilidade','text-button',`data-index="-1"`))}</div><div class="section-gap">${card('Inventário e artefatos',`<div class="grid">${e.items.map((a,i)=>`<div class="list-item"><div class="list-item-head"><h4>${esc(a.name)} ×${a.qty}</h4>${btn('edit-item','Editar','outline small',`data-index="${i}"`)}</div><p>${esc(a.notes)}</p><p>Espaços: ${a.spaces} cada · armadura ${a.armor} · ${a.equipped?'equipado':'guardado'}</p>${btn('delete-entry','Excluir','text-button',`data-kind="items" data-index="${i}"`)}</div>`).join('')||'<p class="hint">Inventário livre para posses, moedas, munições e efeitos de artefatos selados. Para recarregar, informe a reserva no ataque.</p>'}</div>${e.mode==='auto'?`<p class="hint">Carga: ${d.weight}/${d.capacity} espaços. A maior armadura equipada vale; armaduras não se somam.</p>`:''}`,btn('edit-item','+ Item','text-button',`data-index="-1"`))}</div>`;
 return `${btn('back-sheets','‹ Todas as fichas','text-button back')}<div class="detail-header"><div><div class="eyebrow">${e.mode==='auto'?'BEYONDER · CÁLCULO AUTOMÁTICO':e.mode==='narrative'?'PERFIL NARRATIVO':'TOTAIS DO PERFIL'}</div><h2>${esc(e.name)}</h2></div><div class="actions">${e.source?btn('note','Abrir no livro','outline small',`data-id="${esc(e.source)}"`):''}${btn('duplicate','Duplicar','outline small',`data-id="${e.id}"`)}${btn('combat-add','+ Encontro','outline small',`data-id="${e.id}"`)}${btn('delete-entity','Excluir','danger small',`data-id="${e.id}"`)}</div></div><div class="tabbar">${[['perfil','Perfil e segredos'],['valores','Valores e condições'],['arsenal','Ataques, habilidades e itens']].map(([k,v])=>btn('sheet-tab',v,k===sheetTab?'active':'',`data-tab="${k}"`)).join('')}</div>${body}`;
}
function renderCombat(){const c=sess().combat;return `<div class="toolbar"><select id="encounter-select" aria-label="Encontro preparado">${opts([['','Escolha um encontro…'],...SEED.encounters.map(v=>[v.id,v.name])],'')}</select>${btn('combat-picker','+ Participante','')}${btn('initiative','Rolar iniciativas','outline')}${btn('end-combat','Encerrar encontro','outline')}</div>${c.participants.length?`<div class="combat-banner"><div><div class="eyebrow">${c.active?'EM COMBATE':'ENCONTRO PREPARADO'}</div><h2>Rodada ${c.round}</h2><small>Turno de ${esc(ent(c.participants[c.index]?.entityId)?.name||'—')}</small></div><div class="actions">${btn('next-turn','Próximo turno →','')}</div></div><p class="hint">Ações e reações renovam no início do próprio turno. Aplique efeitos de fim de turno antes de avançar. Estar a 0 de Vida exige sobrevivência no começo do turno, salvo estabilização.</p><div class="grid asymmetric"><div class="stack">${c.participants.map((p,i)=>{const e=ent(p.entityId),d=G.stats(e);return `<article class="combat-row ${c.index===i?'active':''}"><div class="combat-initiative"><input type="number" value="${p.initiative}" data-initiative="${p.id}" aria-label="Iniciativa de ${esc(e.name)}"><span>INICIATIVA</span></div><div class="combat-content"><div class="entity-heading"><h3>${esc(e.name)}</h3>${pill(roles[e.role],e.role==='adversary'?'red':'teal')}${btn('open-entity','Ficha','text-button',`data-id="${e.id}"`)}</div>${resources(e,true)}${statline(e)}${flags(e)}<div class="checks"><label class="check"><input type="checkbox" data-combat-flag="action" data-id="${p.id}" ${p.action?'checked':''}>Ação usada</label><label class="check"><input type="checkbox" data-combat-flag="reaction" data-id="${p.id}" ${p.reaction?'checked':''}>Reação usada</label></div><div class="actions">${e.attacks.length?btn('attack','Atacar','',`data-id="${e.id}"`):''}${btn('resource','Dano / cura','outline small',`data-id="${e.id}"`)}${btn('end-effects','Efeitos de fim','outline small',`data-id="${e.id}"`)}${btn('combat-remove','Remover','text-button',`data-id="${p.id}"`)}</div>${e.attacks.filter(a=>a.usesAmmo).map(a=>`<p class="hint" style="margin:8px 0 0">${esc(a.name)}: ${a.ammo}/${a.capacity} · reserva ${a.reserve}</p>`).join('')}</div></article>`;}).join('')}</div><div class="stack">${card('Contexto e perigos',`<label>Posições, alcance, terreno e rotas<textarea data-session="combat.note">${esc(c.note)}</textarea></label><div class="divider"></div><p class="hint">DF/DM exibidas são bases. A janela de ataque acrescenta reação, cobertura, Fadiga III e Exposto/Cego. Caído, alcance, Oculto, Amedrontado e preparações dependem de você.</p>${btn('help','Consultar regras','outline small')}`)}${card('Relógios',sess().clocks.map(clockView).join(''))}${card('Registro de combate',`<div class="log">${sess().log.slice(-15).reverse().map(logView).join('')}</div>`)}</div></div>`:empty('Prepare a cena','Adicione participantes ou escolha um encontro da sessão. As fichas compartilham Vida, condições e inventário entre cenas.',btn('encounter','Começar com André','',`data-id="abertura"`))}`;}
function renderClues(){const s=sess();return `<div class="grid four">${Object.entries({A:'Dois procedimentos',B:'Fuga não é cura',C:'Lucien sobreviveu',D:'Rumo a Bellombre'}).map(([key,title])=>{const found=s.clues.filter(c=>c.found&&c.conclusions.includes(key));return card(`${key} · ${title}`,`<div class="big-number">${found.length}</div><p class="hint">fontes encontradas · ${found.map(c=>esc(c.title.split(' · ')[0])).join(', ')||'Ainda sem pistas marcadas'}</p>`);}).join('')}</div><div class="toolbar section-gap"><p class="hint" style="flex:1;margin:0">Encontrada = o grupo obteve a informação. Entregue = material mostrado aos jogadores.</p>${btn('new-clue','+ Pista','')}${btn('map','Abrir teia de pistas','outline',`data-id="02-Teia-de-pistas"`)}</div><div class="grid">${s.clues.map(c=>`<article class="card clue-card ${c.found?'found':''} ${c.shared?'shared':''}"><div class="card-title"><h3>${esc(c.title)}</h3>${c.shared?pill('Entregue','teal'):c.found?pill('Encontrada','gold'):pill('Oculta')}</div><p>${esc(c.summary)}</p><div class="source-links">${c.sources.map(src=>pill(src)).join('')}</div><div class="checks"><label class="check"><input type="checkbox" data-clue-flag="found" data-id="${esc(c.id)}" ${c.found?'checked':''}>Encontrada</label><label class="check"><input type="checkbox" data-clue-flag="shared" data-id="${esc(c.id)}" ${c.shared?'checked':''}>Entregue aos jogadores</label></div><label class="section-gap">O que o grupo concluiu<textarea data-clue-notes="${esc(c.id)}">${esc(c.notes)}</textarea></label><div class="actions section-gap">${LIBRARY[c.id]?btn('note','Detalhes do mestre','outline small',`data-id="${esc(c.id)}"`):''}${c.handout&&LIBRARY[c.handout]?btn('handout','Mostrar handout','outline gold small',`data-id="${esc(c.handout)}"`):''}${btn('edit-clue','Editar','text-button',`data-id="${esc(c.id)}"`)}</div></article>`).join('')}</div>`;}
function renderLibrary(){const entries=Object.entries(LIBRARY).filter(([k,v])=>(!libraryFolder||v.folder===libraryFolder)&&norm(v.title+' '+v.search).includes(norm(libraryQuery)));const folders=[...new Set(Object.values(LIBRARY).map(v=>v.folder))];return `<div class="grid three">${Object.entries(MAPS).map(([k,v])=>btn('map',`<span>⌘</span>${esc(v.title)}<small>Mapa navegável · abra os cartões e acompanhe as relações</small>`,'map-tile',`data-id="${esc(k)}"`)).join('')}</div><div class="actions section-gap">${btn('floorplan','Planta do mestre','outline',`data-id="mestre"`)}${btn('floorplan','Planta dos jogadores','outline',`data-id="jogadores"`)}${btn('custom-note','+ Nota pessoal','outline',`data-id=""`)}</div><div class="toolbar section-gap"><input id="library-search" class="search" type="search" placeholder="Pesquisar nas 46 notas do Obsidian…" value="${esc(libraryQuery)}" aria-label="Pesquisar biblioteca"><select id="library-folder" aria-label="Pasta da biblioteca">${opts([['','Todas as pastas'],...folders.map(f=>[f,f||'Início'])],libraryFolder)}</select></div><p class="hint">Conteúdo revisado da sessão 1. ${entries.length} notas. Notas e mapas originais ficam preservados; use notas pessoais para seus acréscimos.</p><div class="library-grid">${entries.map(([k,v])=>btn(k.startsWith('H0')?'handout':'note',`<small>${esc(v.folder||'INÍCIO')}</small><span>${esc(v.title)}</span><em>${esc(k)}</em>`,'note-link',`data-id="${esc(k)}"`)).join('')}</div>${state.customNotes.length?`<h2 class="section-gap">Suas notas</h2><div class="library-grid">${state.customNotes.map(v=>btn('custom-note',`<small>NOTA PESSOAL</small><span>${esc(v.title)}</span>`,'note-link',`data-id="${v.id}"`)).join('')}</div>`:''}<div class="section-gap">${downloadsView()}</div>`;}
function logView(v){let date;try{date=new Date(v.at).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});}catch{date=v.at;}return `<div class="log-entry"><time>${esc(date)}</time>${esc(v.text)}</div>`;}
function downloadsView(){return card('Arquivos para levar à mesa',`<div class="download"><span>Aplicativo Android · Mestre<small>Instala ao lado do app dos jogadores · Android 8+</small></span><a class="download-anchor" href="https://arquivo-beyonder-7c24.gui-olialves2.chatgpt.site/downloads/arquivo-beyonder-mestre.apk" download>Baixar APK ↓</a></div>${[['regras-essenciais.pdf','Regras essenciais','4 páginas · PDF'],['sessao-1-guia-do-mestre.pdf','Guia completo da sessão','PDF · roteiro do mestre'],['sessao-1-handouts.pdf','Handouts dos jogadores','PDF · 8 materiais'],['sessao-1-obsidian.zip','Vault do Obsidian','ZIP · notas, Canvas e plantas']].map(([f,t,d])=>`<div class="download"><span>${t}<small>${d}</small></span>${btn('asset','Salvar ↓','outline small',`data-file="${f}"`)}</div>`).join('')}`);}
function renderRecords(){const s=sess();return `<div class="grid">${card('Caderno da sessão',`<div class="form-grid"><label>Título<input data-session="name" value="${esc(s.name)}"></label><label>Data<input type="date" data-session="date" value="${esc(s.date)}"></label></div><label class="section-gap">Resumo, decisões, dívidas e perguntas para a próxima sessão<textarea style="min-height:280px" data-session="notes">${esc(s.notes)}</textarea></label><div class="actions section-gap">${btn('log-entry','+ Anotação no registro','outline')}${btn('delete-session','Excluir sessão','danger small')}</div>`)}<div class="stack">${card('Backup e importação',`<p class="hint">O navegador e o APK guardam dados separados neste aparelho. Exporte e importe para transferir sua mesa. Reinstalar ou limpar dados sem backup pode apagá-la.</p><div class="actions">${btn('backup','↓ Exportar mesa completa','')}${btn('import-gm','↑ Restaurar backup','outline')}${btn('import-players','Importar fichas dos jogadores','outline')}</div><p class="hint section-gap">Restauração substitui a mesa após revisão. Importar jogadores adiciona cópias; o app deles não é alterado.</p>${broken?`<div class="warning">Arquivo original preservado.<div class="actions section-gap">${btn('raw-backup','Exportar original','outline')}${btn('reset-broken','Recomeçar mesa','danger')}</div></div>`:''}`)}${downloadsView()}</div></div><div class="section-gap">${card('Histórico da sessão',`<div class="log">${s.log.length?s.log.slice().reverse().map(logView).join(''):'<p class="hint">Rolagens e alterações ficarão registradas aqui.</p>'}</div>`,btn('export-log','Exportar texto','text-button'))}</div>`;}
function modal(title,body,wide=false,kicker='ARQUIVO DO MESTRE'){const d=$('#dialog');d.classList.toggle('wide-dialog',wide);$('#dialog-title').textContent=title;$('#dialog-kicker').textContent=kicker;$('#dialog-body').innerHTML=body;if(!d.open)d.showModal();d.scrollTop=0;}
function close(){ $('#dialog').close(); }
const formEnd=(text='Salvar')=>`<div class="dialog-actions">${btn('close','Cancelar','outline')}<button type="submit">${text}</button></div></form>`;
function confirmAction(title,text,fn){modal(title,`<p>${esc(text)}</p><div class="dialog-actions">${btn('close','Cancelar','outline')}<button id="confirm-action" class="danger">Confirmar</button></div>`);$('#confirm-action').onclick=()=>{close();fn();};}
function showNote(id){const v=LIBRARY[id];if(!v){toast('Nota não encontrada.');return;}modal(v.title,`<div class="actions" style="margin-bottom:18px">${btn('map','Teia de pistas','outline small',`data-id="02-Teia-de-pistas"`)}</div><article class="prose">${v.body}</article>`,true,v.folder||'BIBLIOTECA');}
function showHandout(id){const v=LIBRARY[id];if(!v)return;modal(v.title,`<div class="notice">Modo de exibição aos jogadores: somente o documento abaixo. Feche para voltar ao material do mestre.</div><div class="actions" style="margin:15px 0">${btn('print','Imprimir / salvar PDF','outline')}${btn('copy-handout','Copiar texto','outline',`data-id="${esc(id)}"`)}</div><article class="prose handout-view" id="handout-content">${v.body}</article>`,true,'DOCUMENTO DOS JOGADORES · SEM NOTAS DO MESTRE');$('#handout-content').querySelectorAll('a[data-note],a[data-map]').forEach(a=>{a.removeAttribute('data-note');a.removeAttribute('data-map');a.removeAttribute('href');});}
function showMap(id){const m=MAPS[id];if(!m)return;mapZoom=1;modal(m.title,`<div class="map-tools">${btn('zoom','−','outline small',`data-delta="-.25" aria-label="Diminuir mapa"`)}${btn('zoom','+','outline small',`data-delta=".25" aria-label="Ampliar mapa"`)}${btn('zoom-reset','Ajustar','outline small')}<span id="zoom-label">100% · role para explorar</span></div><div class="map-viewport"><div class="map-stage">${m.svg}</div></div><p class="hint">Toque nos cartões para abrir as notas. Amplie e role para percorrer o mapa.</p>`,true,'CANVAS · OBSIDIAN');$$('.map-stage g[data-note]').forEach(n=>{n.setAttribute('tabindex','0');n.setAttribute('role','button');n.setAttribute('aria-label','Abrir '+(LIBRARY[n.dataset.note]?.title||'nota'));});}
function showResource(id){const e=ent(id),d=G.stats(e);modal(`Recursos · ${e.name}`,`${resources(e)}<form data-form="resource" data-id="${e.id}"><div class="form-grid"><label>Operação<select name="operation">${opts([['damage','Dano físico (aplica armadura)'],['san-damage','Dano mental (aplica RM)'],['heal','Recuperar Vida'],['san-heal','Recuperar Sanidade'],['spirit-heal','Recuperar Espiritualidade'],['hp-set','Definir Vida atual'],['san-set','Definir Sanidade atual'],['spirit-set','Definir Espiritualidade atual']],'damage')}</select></label>${input('Quantidade','amount',1,'number','min="0" max="9999" required')}</div><p class="hint">Recuperação só ocorre quando autorizada pela ficção. Marca, crise e ferimentos são indicados no resultado. Nenhum dano mental aumenta a Corrupção sozinho.</p>${formEnd('Aplicar')}`);}
function showAttack(id,index=0){const a=ent(id);if(!a.attacks.length){toast('Adicione ataques na ficha primeiro.');return;}const participants=sess().combat.participants.map(p=>ent(p.entityId)).filter(e=>e.id!==id&&!e.dead),targets=participants.length?participants:state.entities.filter(e=>e.id!==id&&!e.dead);if(!targets.length){toast('Adicione um alvo.');return;}modal(`Ataque · ${a.name}`,`<form data-form="attack" data-id="${id}"><div class="form-grid"><label>Ataque<select name="weapon">${opts(a.attacks.map((w,i)=>[i,`${w.name} · +${w.bonus} · ${w.damage}${w.usesAmmo?` · ${w.ammo} cargas`:''}`]),index)}</select></label><label>Alvo<select name="target">${opts(targets.map(e=>[e.id,`${e.name} · DF ${G.stats(e).df??'—'} / DM ${G.stats(e).dm??'—'}`]),targets[0].id)}</select></label><label>Dados<select name="mode">${opts([['normal','Normal · 2d6'],['advantage','Vantagem · 3d6, dois maiores'],['disadvantage','Desvantagem · 3d6, dois menores']],'normal')}</select></label><label>Cobertura física<select name="cover">${opts([['none','Sem cobertura'],['half','Meia cobertura · +2 DF'],['total','Total · impede ataque direto']],'none')}</select></label>${input('Outras circunstâncias (±4)','modifier',0,'number','min="-4" max="4"')}<label class="check"><input name="reaction" type="checkbox">Alvo usa reação (+2 DF)</label></div><p class="hint">Declare a reação antes de rolar. Precisa de alvo participante com reação livre. Só serve para ataque físico com defesa aplicável. O mestre verifica alcance, aparar/esquivar e visibilidade.</p><div class="notice">Fadiga, Abalado e Desorientado do atacante entram automaticamente. No alvo, Fadiga III e Exposto/Cego alteram a defesa. Outros efeitos entram nas circunstâncias. Bônus dos ataques já são totais.</div>${formEnd('Rolar e aplicar uma vez')}`);}
function damageResult(e,r,title='Dano aplicado'){return `<p><b>${esc(e.name)}</b>: ${r.dealt} de ${r.before===undefined?'dano':r.after===e.resources.san&&r.crisis?'Sanidade':'dano'} após reduções. Recurso ${r.before} → ${r.after}.</p>${r.grave?'<p class="warning">Ferimento grave registrado. Defina a consequência e o tratamento na ficha.</p>':''}${r.fatal?'<p class="warning">Dano fatal: morte imediata pelas regras da mesa.</p>':''}${r.crisis?`<p class="warning">Exige teste de crise.</p>${btn('crisis','Resolver crise','outline',`data-id="${e.id}"`)}`:''}${r.mark?`<p class="warning">Perda de 10+ de Sanidade: suscetível a 1 episódio de marca. Se já resolveu a mesma ocorrência, não repita.</p>${btn('mark','Resolver marca','outline',`data-id="${e.id}"`)}`:''}${r.breakdown?'<p class="warning">Sanidade 0: descontrole. Resolva a janela de intervenção segundo a fonte.</p>':''}`;}
function editEntry(kind,index){const e=cur();if(!e)return;const a=e[kind][index]||{};let b='';if(kind==='attacks')b=`<div class="form-grid">${input('Nome','name',a.name||'Novo ataque','text','required')}${input('Bônus total (atributo + perícia)','bonus',a.bonus??3,'number','min="-99" max="99" required')}${input('Dano total · ex.: 1d6+1','damage',a.damage||'1d6','text','required')}<label>Tipo<select name="kind">${opts([['physical','Físico · DF e armadura'],['san','Mental · DM e RM']],a.kind||'physical')}</select></label>${input('Alcance','range',a.range||'contato')}${input('Custo Espiritualidade','cost',a.cost||0,'number','min="0" max="999"')}<label class="check wide"><input type="checkbox" name="usesAmmo" ${a.usesAmmo?'checked':''}>Usa munição</label>${input('Munição carregada','ammo',a.ammo||0,'number','min="0"')}${input('Capacidade','capacity',a.capacity||0,'number','min="0"')}${input('Reserva','reserve',a.reserve||0,'number','min="0"')}${input('Recarga por ação','reload',a.reload||0,'number','min="0"')}<div class="wide">${formArea('Efeitos, limitações e notas','notes',a.notes||'')}</div></div><p class="hint">Inclua Força no dano corpo a corpo quando aplicável. O app não soma atributos novamente.</p>`;
 if(kind==='abilities')b=`<div class="form-grid">${input('Nome','name',a.name||'Nova habilidade','text','required')}${input('Custo Espiritualidade','cost',a.cost??2,'number','min="0" max="999"')}<div class="wide">${formArea('Teste, alcance, duração, efeitos e limites','notes',a.notes||'')}</div></div>`;
 if(kind==='items')b=`<div class="form-grid">${input('Nome','name',a.name||'Novo item','text','required')}${input('Quantidade','qty',a.qty??1,'number','min="0" max="9999"')}${input('Espaços por unidade','spaces',a.spaces??1,'number','min="0" max="999"')}${input('Armadura','armor',a.armor||0,'number','min="0" max="99"')}<label class="check wide"><input type="checkbox" name="equipped" ${a.equipped?'checked':''}>Equipado</label><div class="wide">${formArea('Descrição, selamento e efeitos colaterais','notes',a.notes||'')}</div></div>`;
 modal({attacks:'Ataque',abilities:'Habilidade Beyonder',items:'Item / artefato selado'}[kind],`<form data-form="entry" data-kind="${kind}" data-index="${index}">${b}${formEnd()}`);
}
function fileDownload(name,text,type='application/json'){if(window.BeyonderAndroid?.saveText){window.BeyonderAndroid.saveText(name,text,type);return;}const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function importFile(mode){importMode=mode;$('#import-file').value='';$('#import-file').click();}
function resetView(p){page=p;query='';filter='';selected=null;render();window.scrollTo({top:0,behavior:'instant'});}
const actions={
 nav:b=>resetView(b.dataset.page),close,help(){modal('Regras da mesa',`<div class="rules-list"><p><b>Teste:</b> 2d6 + atributo + perícia. Dificuldades 7 / 9 / 12 / 16. Vantagem: 3d6, dois maiores; desvantagem: dois menores. Limite de circunstâncias ±4.</p><p><b>Vida:</b> 10 + 4×VIT + 2×Grau. <b>Espiritualidade:</b> 10 + 3×VON + 2×INT + 5×Grau. Grau = 10 − Sequência. <b>Sanidade:</b> máximo imutável 100.</p><p><b>DF:</b> 7 + FOR + Luta. <b>DM:</b> 7 + VON + Autocontrole. <b>RM:</b> piso(VON/2) + Grau − 1. Iniciativa: 2d6 + INT + Prontidão.</p><p><b>Turno:</b> uma ação, movimento e uma reação. Reação renova no começo do próprio turno. Esquivar ou Aparar aplicável +2 DF. Meia cobertura +2 DF; total impede tiro direto. Contato dá desvantagem ao disparo.</p><p><b>Acerto:</b> total ≥ defesa. Dois 1 sempre erram e deixam Exposto. Margem 5+ soma 2 de dano. Crítico de alvo único: dois 6 com total suficiente ou margem 8+. Adicione um dado básico; nunca dobre bônus fixos.</p><p><b>Dano:</b> físico menos armadura (mínimo 0); mental menos RM (mínimo 1 se houve dano). Impacto ≥ metade da Vida máxima, arredondada para cima, causa ferimento grave. Atingir 0 com impacto ≥ Vida máxima causa morte imediata.</p><p><b>Vida 0:</b> 2d6 + VIT 7 no início do turno; duas falhas matam, dois 1 marcam duas. Sucesso não apaga falhas. Novo dano a 0 marca uma. Medicina 9 com kit estabiliza, sem kit 12.</p><p><b>Fadiga:</b> uma ativação com custo ≥ teto(ESP máxima/3) gera um nível após o efeito. I/II/III: −1/−2/−3 em testes; II não corre; III move 4 m e tem DF/DM −2. ESP 0 implica ao menos Fadiga II para quem possui ESP.</p><p><b>Crise:</b> perder 15+ de Sanidade de uma vez, cruzar 50/20 ou sofrer nova perda com SAN ≤20: VON + Autocontrole 9 (12 se SAN ≤20). Falha causa Abalado e pode constituir episódio de marca.</p><p><b>Marca nesta sessão:</b> perda de SAN ≥10 após RM, falha de crise ou leitura deliberada após aviso permite um episódio: VON + Autocontrole 9 (12 com SAN ≤20); falha +1 Corrupção. Uma vez por ocorrência; no máximo 2 episódios por personagem. O mestre decide quando o gatilho ocorreu.</p><p><b>Contenção não é cura.</b> Sequência 7 não remove o vínculo. Possível intervenção de um semideus pertence ao futuro da campanha.</p><p class="hint">NPCs prontos usam totais abreviados do livro. Casos contextuais, sobrecarga, áreas e efeitos de condições além dos indicados são arbitrados pelo mestre. Use Teste rápido ou ajuste recursos manualmente.</p></div><div class="actions">${btn('asset','Salvar regras essenciais','outline',`data-file="regras-essenciais.pdf"`)}${installPrompt?btn('install','Instalar no navegador',''):''}</div>`,true);},
 undo(){if(!history.length||broken)return;state=history.pop();save();render();toast('Última alteração desfeita.');},
 note:b=>showNote(b.dataset.id),handout:b=>showHandout(b.dataset.id),map:b=>showMap(b.dataset.id),
 zoom(b){mapZoom=clamp(mapZoom+num(b.dataset.delta),.5,4);$('.map-stage').style.width=`${mapZoom*100}%`;$('#zoom-label').textContent=`${Math.round(mapZoom*100)}% · role para explorar`;},
 'zoom-reset'(){mapZoom=1;$('.map-stage').style.width='100%';$('#zoom-label').textContent='100% · role para explorar';},
 floorplan(b){const player=b.dataset.id==='jogadores';modal(player?'Planta dos jogadores':'Instituto Vauquelin · Planta do mestre',`<div class="prose ${player?'handout-view':''}"><img src="maps/planta-${player?'jogadores':'mestre'}.svg" alt="Planta do Instituto Vauquelin"></div><div class="actions section-gap">${btn('print','Imprimir / salvar PDF','outline')}</div>`,true,player?'MATERIAL DOS JOGADORES':'SEGREDOS DO MESTRE');},
 scene(b){mutate('Cena atual: '+(SEED.scenes.find(s=>s.id===b.dataset.id)?.title||''),()=>{sess().scene=b.dataset.id;for(const e of state.entities)e.overloadUsed=false;});},
 'clock-step'(b){mutate('',()=>{const c=sess().clocks.find(c=>c.id===b.dataset.id);c.value=clamp(c.value+num(b.dataset.delta),0,c.max);G.record(state,`${c.name}: ${c.value}/${c.max}.`);});},
 'new-clock'(){modal('Novo relógio',`<form data-form="clock"><div class="form-grid">${input('Nome','name','','text','required maxlength="120"')}${input('Segmentos (1–24)','max',6,'number','min="1" max="24" required')}<div class="wide">${formArea('Gatilhos e consequências','note')}</div></div>${formEnd('Criar relógio')}`);},
 'new-session'(){modal('Próxima sessão',`<form data-form="session">${input('Nome','name',`Sessão ${state.sessions.length+1}`,'text','required maxlength="160"')}<label class="check section-gap"><input type="checkbox" name="prepared">Copiar pistas e relógios iniciais da sessão 1</label><label class="check section-gap"><input type="checkbox" name="resetMarks" checked>Zerar contadores de episódios de marca (não a Corrupção)</label><p class="hint section-gap">As fichas e os recursos atuais continuam. A sessão anterior fica arquivada no seletor.</p>${formEnd('Abrir sessão')}`);},
 'delete-session'(){if(state.sessions.length===1){toast('Mantenha pelo menos uma sessão.');return;}confirmAction('Excluir esta sessão?',`Apaga notas, pistas, relógios e histórico de “${sess().name}”. As fichas permanecem.`,()=>mutate('',()=>{state.sessions=state.sessions.filter(s=>s.id!==state.activeSession);state.activeSession=state.sessions.at(-1).id;}));},
 'open-entity'(b){selected=b.dataset.id;sheetTab='perfil';page='fichas';render();window.scrollTo({top:0,behavior:'instant'});},'back-sheets'(){selected=null;render();},'sheet-tab'(b){sheetTab=b.dataset.tab;render();},
 'new-entity'(){modal('Nova ficha',`<form data-form="entity"><div class="form-grid">${input('Nome','name','','text','required maxlength="120"')}<label>Papel<select name="role">${opts(Object.entries(roles),'neutral')}</select></label><label>Tipo de ficha<select name="mode">${opts([['simple','Perfil abreviado · valores manuais'],['auto','Beyonder · cálculos automáticos'],['narrative','Narrativo · sem combate definido']],'simple')}</select></label><label>Caminho (para Beyonder)<select name="path">${opts(Object.entries(G.PATHS).map(([k,v])=>[k,v.name]),'vidente')}</select></label></div><p class="hint">Beyonders começam na Sequência 9 com atributos de exemplo; ajuste a distribuição, perícias e poderes conforme a criação aprovada.</p>${formEnd('Criar ficha')}`);},
 duplicate(b){mutate('Ficha duplicada.',()=>{const e=G.clone(ent(b.dataset.id));e.id=G.uid();e.name+=' · cópia';state.entities.push(e);selected=e.id;sheetTab='perfil';page='fichas';});},
 'delete-entity'(b){const e=ent(b.dataset.id);confirmAction('Excluir ficha?',`Remove ${e.name} e suas participações em encontros. Você poderá desfazer a alteração nesta abertura do app.`,()=>mutate('Ficha excluída: '+e.name,()=>{state.entities=state.entities.filter(v=>v.id!==e.id);for(const s of state.sessions){s.combat.participants=s.combat.participants.filter(p=>p.entityId!==e.id);s.combat.index=Math.min(s.combat.index,Math.max(0,s.combat.participants.length-1));}selected=null;}));},
 resource:b=>showResource(b.dataset.id),
 spirit(b){const e=ent(b.dataset.id);modal(`Espiritualidade · ${e.name}`,`<form data-form="spirit" data-id="${e.id}">${input('Custo desta ativação','cost',2,'number','min="0" max="999" required')}<p class="hint section-gap">Atual ${e.resources.spirit}/${G.stats(e).spirit}. Gasto concentrado a partir de ${G.stats(e).threshold} gera Fadiga após o efeito. Sem sobrecarga automática.</p>${formEnd('Gastar Espiritualidade')}`);},
 'edit-attack':b=>editEntry('attacks',num(b.dataset.index)),'edit-ability':b=>editEntry('abilities',num(b.dataset.index)),'edit-item':b=>editEntry('items',num(b.dataset.index)),
 'delete-entry'(b){const kind=b.dataset.kind;if(!['attacks','abilities','items'].includes(kind))return;confirmAction('Excluir registro?','Este registro será removido da ficha.',()=>mutate('Registro removido de '+cur().name,()=>cur()[kind].splice(num(b.dataset.index),1)));},
 'use-ability'(b){const e=ent(b.dataset.id),a=e.abilities[num(b.dataset.index)];let result;mutate(`${e.name} usou ${a.name}: ${a.cost} ESP.`,()=>{result=G.spend(e,a.cost);});if(result)toast(`${a.cost} ESP gastos.${result.generated?' Fadiga aumentou.':''} Resolva o efeito descrito na habilidade.`);},
 reload(b){const e=ent(b.dataset.id),p=sess().combat.participants.find(p=>p.entityId===e.id);mutate('',()=>{if(p?.action)throw Error('Ação já usada.');const n=G.reload(e,num(b.dataset.index));if(p)p.action=true;G.record(state,`${e.name} recarregou ${n} cartuchos usando a ação.`);});},
 attack:b=>showAttack(b.dataset.id,num(b.dataset.index)),
 mark(b){const e=ent(b.dataset.id);confirmAction('Resolver episódio de marca?',`${e.name}: ${e.markChecks}/2 episódios nesta sessão; Corrupção ${e.corruption}/6. Use somente quando o gatilho ocorrer e ainda não tiver sido resolvido.`,()=>{let r;mutate('',()=>{r=G.mentalCheck(e,'mark');G.record(state,`${e.name} · marca: [${r.dice}] → ${r.total} vs. ${r.dc}. ${r.failed?'Falha, +1 Corrupção.':'Resistiu.'}`);});if(r)modal('Episódio de marca',`<div class="roll-result"><div class="big-number">${r.total} <small>vs. ${r.dc}</small></div><p>${r.failed?'Falha: +1 Corrupção.':'Resistiu à progressão da marca.'}</p><p>${esc(e.name)} · ${e.corruption}/6 · ${e.markChecks}/2 episódios.</p>${e.corruption>=6?'<p class="warning">Corrupção 6: descontrole. Resolva a intervenção segundo a fonte.</p>':''}</div>`);});},
 crisis(b){const e=ent(b.dataset.id);let r;mutate('',()=>{r=G.mentalCheck(e,'crisis');G.record(state,`${e.name} · crise: [${r.dice}] → ${r.total} vs. ${r.dc}. ${r.failed?'Falha: Abalado.':'Sucesso.'}`);});if(r)modal('Teste de crise',`<div class="roll-result"><div class="big-number">${r.total} <small>vs. ${r.dc}</small></div><p>${r.failed?'Falha: Abalado. Pode constituir um episódio de marca, se ainda não resolveu esta ocorrência.':'Sucesso: crise resistida.'}</p>${r.failed&&e.markChecks<2?btn('mark','Resolver episódio de marca','outline',`data-id="${e.id}"`):''}</div>`);},
 death(b){const e=ent(b.dataset.id);let r;mutate('',()=>{r=G.deathCheck(e);G.record(state,`${e.name} · sobrevivência: [${r.dice}] → ${r.total} vs. 7. ${e.deathFails}/2 falhas. ${e.dead?'Morreu.':''}`);});if(r)toast(`${e.name}: ${r.total} vs. 7. Falhas ${e.deathFails}/2.${e.dead?' Morto.':''}`);},
 stabilize(b){mutate('',()=>{const e=ent(b.dataset.id);if(e.dead||e.resources.hp>0)throw Error('Só estabilize quem está vivo a 0 de Vida.');e.conditions=e.conditions.filter(c=>c!=='Sangrando');if(!e.conditions.includes('Estabilizado'))e.conditions.push('Estabilizado');G.record(state,`${e.name} estabilizado após cuidados aprovados. Sem cura de Vida.`);});},
 'combat-add'(b){mutate('',()=>{G.addParticipant(state,b.dataset.id);G.record(state,ent(b.dataset.id).name+' entrou no encontro.');});},
 'combat-picker'(){const existing=sess().combat.participants.map(p=>p.entityId),available=state.entities.filter(e=>!existing.includes(e.id));if(!available.length){toast('Todas as fichas estão no encontro. Duplique para criar outro inimigo.');return;}modal('Adicionar ao encontro',`<form data-form="participant"><label>Ficha<select name="entityId">${opts(available.map(e=>[e.id,`${e.name} · ${roles[e.role]}`]),available[0].id)}</select></label>${formEnd('Adicionar')}</form>`);},
 encounter(b){const go=()=>mutate('Encontro preparado: '+(SEED.encounters.find(v=>v.id===b.dataset.id)?.name||''),()=>{G.startEncounter(state,b.dataset.id);page='combate';});if(sess().combat.participants.length)confirmAction('Preparar novo encontro?','Substitui somente a lista e os turnos do encontro atual; os recursos das fichas são mantidos.',go);else go();},
 initiative(){if(!sess().combat.participants.length){toast('Adicione participantes primeiro.');return;}mutate('Iniciativas roladas e ordenadas. Rodada 1.',()=>G.rollInitiative(state));},
 'next-turn'(){mutate('',()=>{const e=G.nextTurn(state);G.record(state,`Rodada ${sess().combat.round} · turno de ${e.name}.`);});},
 'end-combat'(){confirmAction('Encerrar encontro?','Limpa a lista de turnos. Vida, munição, condições e registros permanecem nas fichas.',()=>mutate('Encontro encerrado.',()=>Object.assign(sess().combat,{active:false,participants:[],index:0,round:1})));},
 'combat-remove'(b){mutate('',()=>{const c=sess().combat,idx=c.participants.findIndex(p=>p.id===b.dataset.id);if(idx<0)return;const e=ent(c.participants[idx].entityId);c.participants.splice(idx,1);if(idx<c.index)c.index--;c.index=Math.min(c.index,Math.max(0,c.participants.length-1));G.record(state,e.name+' saiu do encontro.');});},
 'end-effects'(b){const e=ent(b.dataset.id),burn=e.conditions.includes('Em chamas'),bleed=e.conditions.includes('Sangrando');if(!burn&&!bleed){toast('Sem Sangrando ou Em chamas. Outros efeitos dependem da fonte.');return;}confirmAction('Aplicar efeitos de fim do turno?',`${e.name}: ${bleed?'Sangrando: 1 de Vida sem armadura. ':''}${burn?'Em chamas: 1d6 de Vida, sem redução automática. ':''}Aplique uma vez neste turno.`,()=>mutate('',()=>{if(bleed){const r=G.applyDamage(e,1,'physical',false);G.record(state,`${e.name}: Sangrando, ${r.dealt} de Vida.`);}if(burn){const d=G.rollDamage('1d6').total,r=G.applyDamage(e,d,'physical',false);G.record(state,`${e.name}: Em chamas, ${r.dealt} de Vida. Avaliar proteção específica.`);}}));},
 'new-clue'(){editClue();},'edit-clue':b=>editClue(b.dataset.id),
 'custom-note'(b){const n=state.customNotes.find(n=>n.id===b.dataset.id);modal(n?'Editar nota pessoal':'Nova nota pessoal',`<form data-form="custom-note" data-id="${n?.id||''}">${input('Título','title',n?.title||'','text','required maxlength="160"')}<div class="section-gap">${formArea('Texto (links, anotações e lembretes)','body',n?.body||'')}</div><p class="hint">Texto simples, preservado no backup. As notas originais permanecem na biblioteca.</p>${n?btn('delete-note','Excluir nota','danger small',`data-id="${n.id}"`):''}${formEnd()}`);},
 'delete-note'(b){confirmAction('Excluir nota pessoal?','A nota será removida do seu caderno.',()=>mutate('Nota pessoal excluída.',()=>{state.customNotes=state.customNotes.filter(n=>n.id!==b.dataset.id);}));},
 'quick-test'(){modal('Teste rápido',`<form data-form="test"><div class="form-grid"><label>Ficha<select name="entityId">${opts(state.entities.map(e=>[e.id,e.name]),selected||state.entities[0]?.id)}</select></label><label>Atributo<select name="attr">${opts(Object.entries(ATTRS),'int')}</select></label><label>Perícia<select name="skill">${opts([['','Sem perícia'],...G.SKILLS.map(s=>[s,s])],'Investigação')}</select></label>${input('Dificuldade','dc',9,'number','min="0" max="999"')}<label>Dados<select name="mode">${opts([['normal','Normal'],['advantage','Vantagem'],['disadvantage','Desvantagem']],'normal')}</select></label>${input('Outras circunstâncias (±4)','modifier',0,'number','min="-4" max="4"')}<label class="check wide"><input type="checkbox" name="readyTotal">Usar um bônus pronto em vez de atributo + perícia</label>${input('Bônus pronto (NPC abreviado)','bonus',3,'number','min="-99" max="99"')}</div><p class="hint">Fadiga e Abalado entram automaticamente. 7 rotineiro sob pressão · 9 desafiador · 12 difícil · 16 extraordinário. Sem críticos automáticos para testes gerais.</p>${formEnd('Rolar teste')}`);},
 'log-entry'(){modal('Anotar acontecimento',`<form data-form="log">${formArea('Texto','text')}${formEnd('Registrar')}`);},
 backup(){const data=G.backup(state);if(window.BeyonderAndroid?.saveBackup)window.BeyonderAndroid.saveBackup(data);else fileDownload(`beyonder-mestre-${new Date().toISOString().slice(0,10)}.json`,data);toast('Backup preparado. Escolha onde salvá-lo.');},
 'export-log'(){fileDownload('registro-da-sessao.txt',sess().name+'\n\n'+sess().notes+'\n\n'+sess().log.map(v=>v.at+' · '+v.text).join('\n'),'text/plain');},
 'import-gm'(){importFile('gm');},'import-players'(){importFile('players');},
 'raw-backup'(){if(broken)fileDownload('beyonder-mestre-original-nao-lido.json',broken);},
 'reset-broken'(){confirmAction('Recomeçar com o material inicial?','Exporte o arquivo original antes. Esta ação substitui os dados locais que não puderam ser lidos.',()=>{broken=null;state=G.createState();history=[];save();render();});},
 async asset(b){const f=b.dataset.file;if(!['regras-essenciais.pdf','sessao-1-guia-do-mestre.pdf','sessao-1-handouts.pdf','sessao-1-obsidian.zip'].includes(f))return;if(window.BeyonderAndroid?.saveAsset){window.BeyonderAndroid.saveAsset(f);return;}const a=document.createElement('a');a.href='downloads/'+f;a.download=f;a.click();},
 print(){if(window.BeyonderAndroid?.printSheet)window.BeyonderAndroid.printSheet();else window.print();},
 async 'copy-handout'(b){const n=LIBRARY[b.dataset.id];if(!n)return;const t=document.createElement('div');t.innerHTML=n.body;const plain=t.innerText;try{await navigator.clipboard.writeText(plain);toast('Documento copiado.');}catch{modal('Texto para copiar',`<textarea style="min-height:350px" readonly>${esc(plain)}</textarea>`);}},
 async install(){if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}}
};
function editClue(id){const c=sess().clues.find(c=>c.id===id);modal(c?'Editar pista':'Nova pista',`<form data-form="clue" data-id="${c?.id||''}">${input('Título','title',c?.title||'','text','required maxlength="160"')}<div class="section-gap">${formArea('Informação e locais onde pode aparecer','summary',c?.summary||'')}</div><div class="section-gap">${formArea('Anotações do mestre','notes',c?.notes||'')}</div>${formEnd()}`);}
function getForm(form){const d=new FormData(form);return Object.fromEntries(d.entries());}
const forms={
 clock(f,v){mutate('Novo relógio: '+v.name,()=>sess().clocks.push({id:G.uid(),name:v.name,max:clamp(Math.trunc(num(v.max)),1,24),value:0,note:v.note}));close();},
 session(f,v){mutate('',()=>{if(state.sessions.length>=50)throw Error('Limite de 50 sessões. Exporte e arquive as antigas.');const s=G.newSession(v.name,!!v.prepared);state.sessions.push(s);state.activeSession=s.id;if(v.resetMarks)for(const e of state.entities)e.markChecks=0;G.record(state,'Sessão aberta. Contadores de marca '+(v.resetMarks?'zerados.':'mantidos.'));});close();},
 entity(f,v){mutate('Ficha criada: '+v.name,()=>{if(state.entities.length>=300)throw Error('Limite de 300 fichas.');const e=G.createEntity(v.name,v.mode);e.role=v.role;if(v.mode==='auto'&&Object.hasOwn(G.PATHS,v.path)){e.path=v.path;e.attrs={vit:2,for:2,int:2,von:2};e.attrs[G.PATHS[v.path].gains[0]]++;const d=G.stats(e);e.resources={hp:d.hp,san:100,spirit:d.spirit};}state.entities.push(e);selected=e.id;page='fichas';sheetTab='perfil';});close();},
 resource(f,v){const e=ent(f.dataset.id),n=clamp(Math.trunc(num(v.amount)),0,9999);let result;mutate('',()=>{if(v.operation==='damage'||v.operation==='san-damage'){result=G.applyDamage(e,n,v.operation==='damage'?'physical':'san');G.record(state,`${e.name}: ${result.dealt} de dano ${v.operation==='damage'?'físico':'mental'}. ${result.before} → ${result.after}. ${result.grave?'Ferimento grave.':''} ${result.crisis?'Crise.':''} ${result.mark?'Suscetível à marca.':''}`);}else{const key=v.operation.startsWith('san')?'san':v.operation.startsWith('spirit')?'spirit':'hp';e.resources[key]=v.operation.endsWith('-set')?n:e.resources[key]+n;G.reconcile(e);G.record(state,`${e.name}: ${key} ajustado para ${e.resources[key]}.`);}});if(result)modal('Dano aplicado',damageResult(ent(e.id),result));else close();},
 spirit(f,v){let r;mutate('',()=>{const e=ent(f.dataset.id);r=G.spend(e,num(v.cost));G.record(state,`${e.name} gastou ${r.cost} ESP. ${r.generated?'Fadiga aumentou.':''}`);});if(r){close();toast(`${r.cost} ESP gastos.${r.generated?' Fadiga aumentou.':''}`);}},
 entry(f,v){const e=cur(),kind=f.dataset.kind,index=num(f.dataset.index);let a;if(kind==='attacks'){try{G.rollDamage(v.damage,false,()=>0);}catch(err){toast(err.message);return;}a=G.normalizeAttack({...v,usesAmmo:!!v.usesAmmo});if(a.ammo>a.capacity){toast('Munição carregada não pode exceder a capacidade.');return;}}else if(kind==='abilities')a={id:G.uid(),name:v.name,cost:clamp(num(v.cost),0,999),notes:v.notes};else a={id:G.uid(),name:v.name,qty:clamp(num(v.qty),0,9999),spaces:clamp(num(v.spaces),0,999),armor:clamp(num(v.armor),0,99),equipped:!!v.equipped,notes:v.notes};mutate(`${e.name}: ${index<0?'adicionou':'editou'} ${a.name}.`,()=>{if(index<0)e[kind].push(a);else e[kind][index]=a;G.reconcile(e);});close();},
 participant(f,v){mutate('Participante adicionado ao encontro.',()=>G.addParticipant(state,v.entityId));close();},
 attack(f,v){let r;mutate('',()=>{r=G.attack(state,f.dataset.id,v.target,num(v.weapon),{...v,reaction:!!v.reaction});G.record(state,`${r.attacker} → ${r.target} · ${r.weapon}: [${r.kept}] ${r.bonus>=0?'+':''}${r.bonus} = ${r.total} vs. ${r.defense}. ${r.hit?'ACERTO':'ERRO'}${r.critical?' CRÍTICO':''}${r.fumble?' · Exposto':''}.${r.damage?` Dano ${r.damage.dealt}; ${r.kind==='san'?'SAN':'Vida'} ${r.damage.before} → ${r.damage.after}. ${r.damage.grave?'Ferimento grave.':''} ${r.damage.crisis?'Crise.':''}`:''}`);});if(r)modal(r.hit?(r.critical?'Acerto crítico':'Acerto'):'Ataque falhou',`<div class="roll-result"><div class="eyebrow">${esc(r.attacker)} → ${esc(r.target)}</div><div class="dice-line">[ ${r.kept.join(' · ')} ] ${r.bonus>=0?'+':''}${r.bonus}</div><div class="big-number">${r.total} <small>vs. ${r.defense}</small></div><p>${r.hit?`${r.critical?'Crítico: +1 dado básico. ':''}${r.extra?'+2 dano pela margem.':''}`:r.fumble?'Dois 1: erro e atacante Exposto.':'Defesa preservada.'}</p>${r.damage?damageResult(ent(v.target),r.damage):''}<p class="hint">Resultado já aplicado uma vez. Para corrigir, feche e use ↶ Desfazer.</p></div>`);},
 clue(f,v){mutate('Pista salva: '+v.title,()=>{let c=sess().clues.find(c=>c.id===f.dataset.id);if(c)Object.assign(c,{title:v.title,summary:v.summary,notes:v.notes});else sess().clues.push({id:G.uid(),title:v.title,summary:v.summary,notes:v.notes,handout:'',sources:[],conclusions:[],found:false,shared:false});});close();},
 'custom-note'(f,v){mutate('Nota pessoal salva: '+v.title,()=>{let n=state.customNotes.find(n=>n.id===f.dataset.id);if(n)Object.assign(n,{title:v.title,body:v.body});else state.customNotes.push({id:G.uid(),title:v.title,body:v.body});});close();},
 test(f,v){const e=ent(v.entityId);let result;mutate('',()=>{const r=G.rollD6(v.mode),bonus=(v.readyTotal?num(v.bonus):e.attrs[v.attr]+num(e.skills[v.skill]))+clamp(num(v.modifier)-G.penalty(e),-4,4),total=r.kept.reduce((a,b)=>a+b,0)+bonus;result={...r,bonus,total};G.record(state,`${e.name} · teste ${v.readyTotal?'bônus pronto':ATTRS[v.attr]+' + '+(v.skill||'sem perícia')}: [${r.kept}] ${bonus>=0?'+':''}${bonus} = ${total} vs. ${v.dc}. ${total>=num(v.dc)?'Sucesso':'Falha'}.`);});if(result)modal('Resultado do teste',`<div class="roll-result"><div class="eyebrow">${esc(e.name)}</div><div class="dice-line">[ ${result.kept.join(' · ')} ] ${result.bonus>=0?'+':''}${result.bonus}</div><div class="big-number">${result.total} <small>vs. ${num(v.dc)}</small></div><p>${result.total>=num(v.dc)?'Sucesso':'Falha'} · resolva o custo ou consequência da cena.</p></div>`);},
 log(f,v){mutate(v.text,()=>{});close();}
};
document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(b){clearTimeout(editTimer);ev.preventDefault();try{actions[b.dataset.action]?.(b);}catch(e){toast(e.message);}return;}const note=ev.target.closest('[data-note]');if(note){ev.preventDefault();showNote(note.dataset.note);return;}const map=ev.target.closest('[data-map]');if(map){ev.preventDefault();showMap(map.dataset.map);}});
document.addEventListener('keydown',ev=>{if((ev.key==='Enter'||ev.key===' ')&&ev.target.matches('g[data-note]')){ev.preventDefault();showNote(ev.target.dataset.note);}});
document.addEventListener('submit',ev=>{const f=ev.target;if(!f.matches('[data-form]'))return;ev.preventDefault();try{forms[f.dataset.form]?.(f,getForm(f));}catch(e){toast(e.message);}});
function setPath(obj,path,value){const parts=path.split('.');if(parts.some(k=>['__proto__','prototype','constructor'].includes(k)))return;const key=parts.pop();let t=obj;for(const p of parts)t=t[p];t[key]=value;}
document.addEventListener('change',ev=>{const t=ev.target;
 if(t.id==='session-picker'){mutate('',()=>{state.activeSession=t.value;selected=null;});return;}
 if(t.id==='entity-filter'){filter=t.value;render();return;}if(t.id==='library-folder'){libraryFolder=t.value;render();return;}
 if(t.id==='encounter-select'&&t.value){actions.encounter({dataset:{id:t.value}});return;}
 if(t.dataset.field&&cur()){const path=t.dataset.field;mutate('',()=>{const e=cur();let v=t.type==='number'?(t.value===''&&['stats.hp','stats.df','stats.dm'].includes(path)?null:num(t.value)):t.value;if(path==='sequence')v=num(v);if(path.startsWith('stats.')&&v!==null)v=clamp(num(v),path==='stats.initiative'?-99:0,9999);if(path.startsWith('adjust.'))v=clamp(num(v),-100,100);if(path.startsWith('attrs.'))v=clamp(Math.trunc(num(v)),0,5);if(path.startsWith('skills.'))v=clamp(Math.trunc(num(v)),0,e.mode==='auto'?12-e.sequence:12);if(['fatigue','corruption','deathFails','markChecks'].includes(path))v=clamp(Math.trunc(num(v)),0,path==='corruption'?6:path==='fatigue'?3:2);setPath(e,path,v);if(path==='sequence')for(const k of G.SKILLS)e.skills[k]=Math.min(e.skills[k],12-e.sequence);G.reconcile(e);},false);render();return;}
 if(t.dataset.session){mutate('',()=>setPath(sess(),t.dataset.session,t.value),false);if(t.dataset.session==='name')$('#session-picker').innerHTML=opts(state.sessions.map(s=>[s.id,s.name]),state.activeSession);return;}
 if(t.dataset.condition&&cur()){mutate('',()=>{cur().conditions=cur().conditions.filter(c=>c!==t.dataset.condition);if(t.checked)cur().conditions.push(t.dataset.condition);});return;}
 if(t.dataset.checklist){mutate('',()=>{sess().checklist=sess().checklist.filter(c=>c!==t.dataset.checklist);if(t.checked)sess().checklist.push(t.dataset.checklist);},false);return;}
 if(t.dataset.initiative){mutate('',()=>{sess().combat.participants.find(p=>p.id===t.dataset.initiative).initiative=num(t.value);},false);return;}
 if(t.dataset.combatFlag){mutate('',()=>{sess().combat.participants.find(p=>p.id===t.dataset.id)[t.dataset.combatFlag]=t.checked;},false);return;}
 if(t.dataset.clueFlag){mutate('',()=>{const c=sess().clues.find(c=>c.id===t.dataset.id);c[t.dataset.clueFlag]=t.checked;if(c.shared)c.found=true;if(!c.found)c.shared=false;G.record(state,`${c.title}: ${c.shared?'entregue':c.found?'encontrada':'oculta'}.`);});return;}
 if(t.dataset.clueNotes){mutate('',()=>{sess().clues.find(c=>c.id===t.dataset.clueNotes).notes=t.value;},false);}
});
let editTimer,editUndoTarget=null;
document.addEventListener('focusin',ev=>{if(ev.target.matches('[data-field],[data-session],[data-clue-notes]'))editUndoTarget=null;});
document.addEventListener('input',ev=>{const t=ev.target;if(!t.matches('textarea[data-field],input[type=text][data-field],textarea[data-session],input[data-session],textarea[data-clue-notes]'))return;clearTimeout(editTimer);editTimer=setTimeout(()=>{if(!t.isConnected||broken)return;const prior=G.clone(state);if(t.dataset.field&&cur())setPath(cur(),t.dataset.field,t.value);else if(t.dataset.session)setPath(sess(),t.dataset.session,t.value);else if(t.dataset.clueNotes){const c=sess().clues.find(c=>c.id===t.dataset.clueNotes);if(c)c.notes=t.value;}if(editUndoTarget!==t){history.push(prior);if(history.length>25)history.shift();editUndoTarget=t;}save();$('#undo').disabled=!history.length;},400);});
let searchTimer;document.addEventListener('input',ev=>{const t=ev.target;if(!['entity-search','library-search'].includes(t.id))return;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=t.selectionStart,id=t.id;if(id==='entity-search')query=t.value;else libraryQuery=t.value;render();const n=$('#'+id);n.focus();try{n.setSelectionRange(pos,pos);}catch{}},180);});
$('#dialog-close').onclick=close;
$('#import-file').addEventListener('change',async ev=>{const f=ev.target.files[0];if(!f)return;if(f.size>5000000){toast('Arquivo excede 5 MB.');return;}try{const raw=await f.text();if(importMode==='players'){const imported=G.importPlayers(raw);if(imported.length+state.entities.length>300)throw Error('Importação excede 300 fichas.');modal('Importar jogadores',`<p>Adicionar ${imported.length} fichas como cópias:</p><ul>${imported.map(e=>`<li>${esc(e.name)} · ${esc(G.PATHS[e.path].name)} · Sequência ${e.sequence}</li>`).join('')}</ul><p class="hint">Importar novamente cria outra cópia. Os ataques foram extraídos das armas: confira bônus, dano e munição.</p><div class="dialog-actions">${btn('close','Cancelar','outline')}<button id="confirm-import">Adicionar fichas</button></div>`);$('#confirm-import').onclick=()=>{mutate('Fichas de jogadores importadas.',()=>{state.entities.push(...imported);page='fichas';selected=null;});close();};}else{const imported=G.parseBackup(raw);modal('Restaurar mesa completa?',`<p>Backup válido: <b>${imported.entities.length} fichas</b>, <b>${imported.sessions.length} sessões</b> e ${imported.customNotes.length} notas pessoais.</p><p class="warning">Substitui todos os dados desta instalação. Exporte a mesa atual antes de confirmar.</p><div class="dialog-actions">${btn('close','Cancelar','outline')}<button class="danger" id="confirm-import">Restaurar este backup</button></div>`);$('#confirm-import').onclick=()=>{if(broken){broken=null;history=[];}else history.push(G.clone(state));state=imported;selected=null;page='mesa';save();close();render();toast('Mesa restaurada.');};}}catch(e){toast('Arquivo não importado: '+e.message);}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('pagehide',()=>{const t=document.activeElement;if(t?.matches('[data-field],[data-session],[data-clue-notes]'))t.dispatchEvent(new Event('change',{bubbles:true}));save();});
window.addEventListener('online',()=>toast('Conexão disponível. Seus dados continuam locais.'));
if('serviceWorker' in navigator&&!window.BeyonderAndroid)navigator.serviceWorker.register('./sw.js',{scope:'./'}).catch(()=>{});
render();if(!broken)save();
